import {homeAssets} from './home-assets.mjs?v=64aedcf9fcd3';

export function homeHeader(){return `<a class="home-logo brand" href="./" aria-label="人格光谱首页"><span class="mark" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span><span>人格光谱<small>PERSONA SPECTRUM</small></span></a><div class="home-utilities"><button data-action="language" aria-label="語言設定"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m8 4 2 5-4 3 3 3 1 5m6-16-2 5 5 3-1 4-4 4"/></svg></button><button data-action="my-report">你的進度</button></div>`;}

export function homeMarkup(){return `<div class="home-page"><section class="home-hero" aria-labelledby="home-title"><svg class="home-angle" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1920 60" preserveAspectRatio="none" aria-hidden="true"><path d="m0 20 420 40L800 0l750 60 370-45V0H0z" transform="translate(1920 0) scale(-1 1)" fill="white"/></svg><div class="home-copy"><h1 id="home-title">「夢寐以求的被理解之感終于降臨，這種滋味妙不可言。」</h1><p>花 15–20 分鐘，收穫一份關於自己的描述，<br class="home-desktop-break">探索你是何人，以及你所作所為背後的緣由。</p><button class="home-cta" data-action="start-test">進行測試 <svg viewBox="0 0 28 28" fill="none" aria-hidden="true"><path d="M4 14h19m-8-8 8 8-8 8" stroke="currentColor" stroke-width="1.5"/></svg></button></div><picture class="home-panorama"><source media="(min-width:768px)" srcset="${homeAssets['hero-desktop']}"><img src="${homeAssets['hero-mobile']}" width="377" height="201" alt="不同性格的朋友在群山與樹木之間圍著營火野餐"></picture></section><section class="home-metrics" aria-label="測試內容"><dl><div class="home-metric home-blue"><dt>110</dt><dd>探索自己的問題</dd></div><div class="home-metric home-yellow"><dt>16</dt><dd>人格類型介紹</dd></div><div class="home-metric home-green"><dt>5</dt><dd>性格觀察維度</dd></div><div class="home-metric home-purple"><dt>15–20</dt><dd>分鐘完成測試</dd></div></dl></section></div>`;}

export function homeFooter(){return `<div class="home-footer-grid"><div><h2>幫助</h2><button data-action="my-report">找回測試進度</button><button data-action="privacy">數據與隱私</button><button data-action="language">語言設定</button></div></div><div class="home-footer-bottom"><button data-action="language">◎ 繁體中文</button><div><button data-action="method">關於測試</button><button data-action="privacy">隱私政策</button></div><p>© ${new Date().getFullYear()} 人格光譜</p></div>`;}
